{"results": [{"id": "hp_doc_a4f74ac97d1887ce2c2ae4256cf58421c0f5fda72e258242a4fb7467f942cdcc", "title": "Metal Gear Solid: The Twin Snakes", "text": "Metal Gear Solid: The Twin Snakes is an action-adventure stealth video game co-developed by Silicon Knights and Konami Computer Entertainment Japan for the GameCube video game console in March 2004. The game is a remake of \"Metal Gear Solid\", originally developed by Konami for the PlayStation in 1998.", "score": 59.5579}, {"id": "hp_doc_30372305858856e780cf7150a254abde9322f67477b6e04f95b87145b28cd33c", "title": "Metal Gear Solid", "text": "Metal Gear Solid is an action-adventure stealth video game produced by Konami Computer Entertainment Japan and released for the PlayStation in 1998. The game was directed, produced, and co-written by series creator Hideo Kojima, and serves as a sequel to the MSX2 video games \"Metal Gear\" and \"\", which Kojima also wrote and directed.", "score": 55.5902}, {"id": "hp_doc_6bdc20fb92d1a4706a8a5a1628b546983f27e53812bb69db50f0292e31a87bc3", "title": "Metal Gear Solid 3: Snake Eater", "text": "Metal Gear Solid 3: Snake Eater is an action-adventure stealth video game produced by Konami Computer Entertainment Japan for the PlayStation 2. It was released in late 2004 in North America and Japan, then in early 2005 in Europe and Australia. It was the fifth \"Metal Gear\" game written and directed by Hideo Kojima and serves as a prequel to the previous installments.", "score": 54.3585}], "remaining_searches": 1}
